class Solution:
    def countCompleteDayPairs(self, hours: list[int]) -> int:
        cnt = [0] * 24
        ans = 0
        for h in hours:
            rem = h % 24
            comp = (24 - rem) % 24
            ans += cnt[comp]
            cnt[rem] += 1
        return ans

class Solution {
public:
    int countCompleteDayPairs(vector<int>& hours) {
        vector<int> cnt(24, 0);
        int ans = 0;
        for (int h : hours) {
            int rem = h % 24;
            int comp = (24 - rem) % 24;
            ans += cnt[comp];
            cnt[rem]++;
        }
        return ans;
    }
};

class Solution {
    public int countCompleteDayPairs(int[] hours) {
        int[] cnt = new int[24];
        int ans = 0;
        for (int h : hours) {
            int rem = h % 24;
            int comp = (24 - rem) % 24;
            ans += cnt[comp];
            cnt[rem]++;
        }
        return ans;
    }
}

